// Hybrid speech input — lifecycle-safe. Native on Android; Web Speech fallback elsewhere.
const Voice={rec:null,target:null,targetId:'',mode:'',keep:false,stopRequested:false,restart:null,clock:null,watchdog:null,started:0,lastActivity:0,finalText:'',preview:'',committed:false,session:0};
function normalizeSpeech(s){return String(s||'').replace(/\s+/g,'').replace(/[、。,.!?！？]/g,'');}
function mergeSpeechText(base,next){
 const a=String(base||'').trim(),b=String(next||'').trim(),an=normalizeSpeech(a),bn=normalizeSpeech(b);
 if(!an)return b;if(!bn||an===bn)return a;
 // Some mobile engines resend the same final result as one repeated, cumulative string.
 if(bn.length>an.length&&bn.length%an.length===0&&an.repeat(bn.length/an.length)===bn)return a;
 if(an.includes(bn))return a;if(bn.includes(an))return b;
 return `${a} ${b}`;
}
function speechSupport(){return window.SpeechRecognition||window.webkitSpeechRecognition||null;}
function hasNativeVoice(){return !!(window.NativeVoice&&typeof window.NativeVoice.start==='function');}
function setVoiceStatus(label,preview){const s=$('#voiceStatusText');if(s)s.textContent=label||'音声入力中';if(preview!==undefined)$('#voicePreview').textContent=preview;}
function armVoiceWatchdog(){clearTimeout(Voice.watchdog);Voice.watchdog=setTimeout(()=>{if(!Voice.mode)return;Voice.keep=false;Voice.stopRequested=true;setVoiceStatus('音声入力を終了します','長時間音声がなかったため終了しました');if(Voice.mode==='web'){try{Voice.rec&&Voice.rec.stop();}catch{};setTimeout(()=>{if(Voice.mode==='web')finalizeWebVoice();},400);}else if(Voice.mode==='native'){try{hasNativeVoice()&&window.NativeVoice.stop();}catch{};setTimeout(()=>{if(Voice.mode==='native')finishVoiceUi();},1200);}},45000);}
function touchVoice(){Voice.lastActivity=Date.now();armVoiceWatchdog();}
function beginVoiceUi(targetId,mode){
  // Any stale UI/session is synchronously cleared before starting a new session.
  finishVoiceUi(true);
  Voice.session+=1;Voice.target=document.getElementById(targetId);if(!Voice.target)return false;
  Voice.targetId=targetId;Voice.mode=mode;Voice.keep=true;Voice.stopRequested=false;Voice.finalText='';Voice.preview='';Voice.committed=false;Voice.started=Date.now();Voice.lastActivity=Voice.started;
  $('#voiceElapsed').textContent='00:00';$('#voicePanel').hidden=false;setVoiceStatus(mode==='native'?'音声入力を準備中':'音声入力中',mode==='native'?'Android音声認識を準備しています…':'話してください…');
  clearInterval(Voice.clock);Voice.clock=setInterval(()=>{if(!Voice.mode)return;const sec=Math.floor((Date.now()-Voice.started)/1000);$('#voiceElapsed').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;},1000);armVoiceWatchdog();return true;
}
function commitVoiceText(text){text=String(text||'').replace(/\s+/g,' ').trim();if(!Voice.target||!text)return;const before=Voice.target.value.trim();Voice.target.value=before?`${before}\n${text}`:text;Voice.target.dispatchEvent(new Event('input',{bubbles:true}));}
function finishVoiceUi(silent=false){clearInterval(Voice.clock);clearTimeout(Voice.restart);clearTimeout(Voice.watchdog);const panel=$('#voicePanel');if(panel)panel.hidden=true;Voice.rec=null;Voice.target=null;Voice.targetId='';Voice.mode='';Voice.keep=false;Voice.stopRequested=false;Voice.finalText='';Voice.preview='';Voice.committed=false;Voice.started=0;Voice.lastActivity=0;if(!silent){const e=$('#voiceElapsed');if(e)e.textContent='00:00';}}
window.AISeisakuNativeVoice={
 onReady(){if(Voice.mode==='native'){touchVoice();setVoiceStatus('音声入力中','話してください…');}},
 onPartial(text){if(Voice.mode==='native'){touchVoice();setVoiceStatus('音声入力中',text||'話してください…');}},
 onCommitted(text){if(Voice.mode==='native'){touchVoice();setVoiceStatus('音声入力中',text||'認識中…');}},
 onFinalText(text){if(Voice.mode==='native'&&!Voice.committed){Voice.committed=true;commitVoiceText(text);finishVoiceUi();if(String(text||'').trim())toast('音声を入力しました');else toast('音声は認識されませんでした');}},
 onError(message){if(Voice.mode==='native'){finishVoiceUi();toast(message||'音声認識を開始できませんでした');}}
};
function startVoice(targetId){
 if(hasNativeVoice()){if(!beginVoiceUi(targetId,'native'))return;try{window.NativeVoice.start(targetId);}catch{finishVoiceUi();toast('Android音声認識を開始できませんでした');}return;}
 const SR=speechSupport();if(!SR){finishVoiceUi(true);toast('この環境では音声認識が使えません。Androidアプリ版または端末キーボードの音声入力をご利用ください。');return;}
 if(!beginVoiceUi(targetId,'web'))return;
 const rec=new SR();Voice.rec=rec;rec.lang='ja-JP';rec.continuous=false;rec.interimResults=true;rec.maxAlternatives=1;
 rec.onstart=()=>{if(Voice.mode==='web'){touchVoice();setVoiceStatus('音声入力中','話してください…');}};
 rec.onresult=e=>{
  if(Voice.mode!=='web'||Voice.committed)return;touchVoice();let interim='',eventFinal='';
  for(let i=e.resultIndex;i<e.results.length;i++){const txt=e.results[i][0].transcript;if(e.results[i].isFinal)eventFinal=mergeSpeechText(eventFinal,txt);else interim+=txt;}
  if(eventFinal){Voice.finalText=mergeSpeechText(Voice.finalText,eventFinal);Voice.preview='';Voice.keep=false;Voice.stopRequested=true;setVoiceStatus('音声を反映中',Voice.finalText);setTimeout(()=>{if(Voice.mode!=='web')return;try{rec.stop();}catch{};setTimeout(()=>{if(Voice.mode==='web')finalizeWebVoice();},500);},0);}
  else{Voice.preview=interim;$('#voicePreview').textContent=interim||'話してください…';}
 };
 rec.onerror=e=>{if(Voice.mode!=='web')return;const fatal=['not-allowed','service-not-allowed','audio-capture','network'].includes(e.error);if(fatal){Voice.keep=false;Voice.stopRequested=true;const msg=e.error==='not-allowed'||e.error==='service-not-allowed'?'マイク権限がありません。手入力はそのまま利用できます。':'音声認識を継続できませんでした。';finalizeWebVoice();toast(msg);}else if(e.error==='no-speech'){Voice.keep=false;Voice.stopRequested=true;setVoiceStatus('音声を終了します','音声が聞き取れませんでした');} };
 rec.onend=()=>{if(Voice.mode==='web')finalizeWebVoice();};
 try{rec.start();}catch{finishVoiceUi();toast('音声認識を開始できませんでした');}
}
function stopVoice(silent=false){
 if(!Voice.mode){const panel=$('#voicePanel');if(panel)panel.hidden=true;return;}
 Voice.stopRequested=true;Voice.keep=false;clearTimeout(Voice.restart);clearTimeout(Voice.watchdog);setVoiceStatus('音声入力を停止中','認識結果を反映しています…');
 if(Voice.mode==='native'&&hasNativeVoice()){try{window.NativeVoice.stop();}catch{finishVoiceUi();}setTimeout(()=>{if(Voice.mode==='native')finishVoiceUi();},1600);return;}
 if(Voice.mode==='web'){if(!Voice.rec){finishVoiceUi();return;}try{Voice.rec.stop();}catch{finalizeWebVoice();}setTimeout(()=>{if(Voice.mode==='web')finalizeWebVoice();},1000);return;}
 finishVoiceUi(silent);
}
function finalizeWebVoice(){if(Voice.mode!=='web'||Voice.committed)return;Voice.committed=true;const text=Voice.finalText||Voice.preview;commitVoiceText(text);finishVoiceUi();if(String(text||'').trim())toast('音声を入力しました');}
// Defensive boot reset: stale markup/state must never show “音声入力中” before the user presses a mic button.
finishVoiceUi(true);
$$('[data-voice-target]').forEach(b=>b.onclick=e=>{e.preventDefault();startVoice(b.dataset.voiceTarget);});$('#stopVoiceBtn').onclick=()=>stopVoice();


